export const n = 30;
export const num = "30";
export const title = "داخلی Git — packfile، gc، fsck و reftable";
export const label = "فصل ۳۰ · داخلی Git";
export const part = 2;
export const html = "<p class=\"lead\">Git فایل‌ها را اول جدا و بعد فشرده در packfile نگه می‌دارد. gc زباله‌ها را جمع می‌کند. این فصل وقتی لازم می‌شود که مخزن باد کرده یا <code>fsck</code> خطا می‌دهد.</p>\n  <h2><span class=\"hx\"><span class=\"hx-t\">🎯 اهداف یادگیری</span></span></h2>\n<ul>\n<li>loose object را از packfile تشخیص دهی</li>\n<li><code>gc</code> و <code>repack</code> را با احتیاط اجرا کنی</li>\n<li><code>fsck</code> را برای سلامت دیتابیس به کار ببری</li>\n<li>reftable را به‌عنوان backend مدرن refs بشناسی</li>\n</ul>\n<h2><span class=\"hx\"><span class=\"hx-t\">🗄️ objects</span></span></h2>\n<p class=\"keep-next\">دو شکل:</p>\n<ul>\n<li><strong>Loose:</strong> <code>.git/objects/ab/cdef...</code> یک فایل per شیء</li>\n<li class=\"keep-next\"><strong>Packed:</strong> <code>pack-....pack</code> + <code>.idx</code> — دلتا فشرده، سریع برای fetch</li>\n</ul>\n<div class=\"code\"><div class=\"code-head\"><span class=\"dots\"><i></i><i></i><i></i></span><span class=\"fname\">نگاه</span></div><pre>git<span style=\"color: #F8F8F2\"> </span>count-objects<span style=\"color: #F8F8F2\"> </span>-vH\ngit<span style=\"color: #F8F8F2\"> </span>verify-pack<span style=\"color: #F8F8F2\"> </span>-v<span style=\"color: #F8F8F2\"> </span>.git/objects/pack/*.idx<span style=\"color: #F8F8F2\"> | </span>sort<span style=\"color: #F8F8F2\"> </span>-k<span style=\"color: #F8F8F2\"> </span><span style=\"color: #AE81FF\">3</span><span style=\"color: #F8F8F2\"> </span>-n<span style=\"color: #F8F8F2\"> | </span>tail\ngit<span style=\"color: #F8F8F2\"> </span>cat-file<span style=\"color: #F8F8F2\"> </span>-t<span style=\"color: #F8F8F2\"> </span>9f3a1c\ngit<span style=\"color: #F8F8F2\"> </span>cat-file<span style=\"color: #F8F8F2\"> </span>-s<span style=\"color: #F8F8F2\"> </span>9f3a1c\n</pre></div>\n<p><code>git gc</code> looseها را pack می‌کند، unreachable را بعد از grace period دور می‌ریزد. <code>git gc --prune=now</code> تهاجمی است.</p>\n<div class=\"callout callout-warn\"><div class=\"callout-title\">gc وسط کار دیگران</div>\n<p>روی سرور شلوغ <code>gc</code> را در maintenance پنجره بزن. <code>git maintenance start</code> زمان‌بندی امن‌تری است.</p>\n</div>\n<h2><span class=\"hx\"><span class=\"hx-t\">🔗 refs: files در برابر reftable</span></span></h2>\n<p class=\"keep-next\">سنت: هر شاخه یک فایل در <code>.git/refs/heads</code> + <code>packed-refs</code>. با صدها هزار ref (Gerrit، monorepo) کند می‌شود.</p>\n<div class=\"code\"><div class=\"code-head\"><span class=\"dots\"><i></i><i></i><i></i></span><span class=\"fname\">مخزن آزمایشی</span></div><pre>git<span style=\"color: #F8F8F2\"> </span>init<span style=\"color: #F8F8F2\"> </span>--ref-format<span style=\"color: #FF4689\">=</span>reftable<span style=\"color: #F8F8F2\"> </span>/tmp/rt\n</pre></div>\n<p>Reftable در مسیر Git ۳.۰ production-ready است. GitHub در مقیاس خودش از سیستم‌های مشابه بهره می‌برد. برای پروژهٔ معمولی files کافی است.</p>\n<h2><span class=\"hx\"><span class=\"hx-t\">🩺 fsck و recover</span></span></h2>\n<div class=\"code\"><div class=\"code-head\"><span class=\"dots\"><i></i><i></i><i></i></span><span class=\"fname\">سلامت</span></div><pre>git<span style=\"color: #F8F8F2\"> </span>fsck<span style=\"color: #F8F8F2\"> </span>--full\ngit<span style=\"color: #F8F8F2\"> </span>fsck<span style=\"color: #F8F8F2\"> </span>--lost-found\n</pre></div>\n<p>dangling commit اغلب کامیت‌های rebaseشده‌اند — گاهی نجات با <code>git show &lt;hash&gt;</code> و شاخه ساختن.</p>\n<p>اگر <code>index.lock</code> ماند (کریش VS Code): فقط وقتی هیچ فرایند Git/Code روی مخزن نیست حذفش کن.</p>\n<h2><span class=\"hx\"><span class=\"hx-t\">🧹 تاریخچهٔ سنگین</span></span></h2>\n<div class=\"code\"><div class=\"code-head\"><span class=\"dots\"><i></i><i></i><i></i></span><span class=\"fname\">چه چیزی حجم را خورده؟</span></div><pre>git<span style=\"color: #F8F8F2\"> </span>rev-list<span style=\"color: #F8F8F2\"> </span>--objects<span style=\"color: #F8F8F2\"> </span>--all<span style=\"color: #F8F8F2\"> </span><span style=\"color: #AE81FF\">\\</span>\n<span style=\"color: #F8F8F2\">  | </span>git<span style=\"color: #F8F8F2\"> </span>cat-file<span style=\"color: #F8F8F2\"> </span>--batch-check<span style=\"color: #FF4689\">=</span><span style=\"color: #E6DB74\">&#39;%(objecttype) %(objectname) %(objectsize) %(rest)&#39;</span><span style=\"color: #F8F8F2\"> </span><span style=\"color: #AE81FF\">\\</span>\n<span style=\"color: #F8F8F2\">  | </span>awk<span style=\"color: #F8F8F2\"> </span><span style=\"color: #E6DB74\">&#39;/^blob/&#39;</span><span style=\"color: #F8F8F2\"> | </span>sort<span style=\"color: #F8F8F2\"> </span>-k3<span style=\"color: #F8F8F2\"> </span>-n<span style=\"color: #F8F8F2\"> | </span>tail\n</pre></div>\n<p>بعد <code>git filter-repo</code> برای حذف باینری accidental. همه باید re-clone کنند.</p>\n<div class=\"callout callout-interview\"><div class=\"callout-title\">سؤالات مصاحبه (با پاسخ)</div>\n<p><strong>Mid — چرا clone دوم سریع‌تر است؟</strong> pack از قبل دلتا شده؛ looseها در مسیر critical نیستند.</p>\n<p><strong>Senior — unreachable چه زمانی می‌میرد؟</strong> reflog expire (پیش‌فرض ~90 روز) بعد prune. تا آن موقع reset --hard قابل برگشت است.</p>\n</div>\n<h2><span class=\"hx\"><span class=\"hx-t\">✅ چک‌لیست فهم</span></span></h2>\n<div class=\"keep-block\"><div class=\"checklist\">\n<ul>\n<li><code>count-objects -vH</code> را خوانده‌ای</li>\n<li>می‌دانی gc unreachable را بعد از reflog می‌کشد</li>\n<li>reftable را با SHA-256 قاطی نمی‌کنی (دو محور جدا)</li>\n</ul>\n</div><p><strong>فصل بعد:</strong> مخازن بزرگ، partial clone، Scalar، monorepo.</p></div>";
export default { n, num, title, label, part, html };
